const SCHEMA = {
  type:'object', additionalProperties:false, required:['revisions'],
  properties:{ revisions:{ type:'array', items:{
    type:'object', additionalProperties:false,
    required:['number','oldTitle','newTitle','newSlug','mainCharacter','setting','theme','spotlightTerm','spotlightRomanization','spotlightMeaning','premise','arc','reason'],
    properties:{
      number:{type:'integer'},
      oldTitle:{type:'string'},
      newTitle:{type:'string'},
      newSlug:{type:'string', description:'kebab-case, no number prefix'},
      mainCharacter:{type:'string'},
      guests:{type:'string'},
      setting:{type:'string'},
      theme:{type:'string', description:'a lesson DISTINCT from every other story'},
      spotlightTerm:{type:'string'},
      spotlightRomanization:{type:'string'},
      spotlightMeaning:{type:'string'},
      premise:{type:'string'},
      arc:{type:'string'},
      reason:{type:'string', description:'why this one was chosen to rewrite and how it now differs'},
    } } } },
}

const collections = Object.keys(DATA)
const results = await parallel(collections.map(key => () => {
  const d = DATA[key]
  const roadmapList = d.roadmap.map(s=>`#${s.number} "${s.title}" [${s.mainCharacter}] theme="${s.theme}" :: ${s.premise}`).join('\n')
  const existingList = d.existing.length ? ('\nCANONICAL ALREADY-PUBLISHED STORIES (DO NOT CHANGE, treat as fixed):\n'+d.existing.map(s=>`#${s.number} "${s.title}" theme="${s.theme}"`).join('\n')) : ''
  const clusterList = d.clusters.map((c,i)=>`Cluster ${i+1} [${c.severity}]: ${c.titles.join('  ||  ')}\n   reason: ${c.reason}`).join('\n')
  const prompt = `You are fixing THEMATIC REPETITION in the ${key} collection of cozy bedtime stories for a 9-year-old girl. A duplicate-check found clusters of stories that are too similar in PREMISE + LESSON (often the same recurring character learning the same lesson repeatedly).

YOUR JOB: For each cluster, KEEP the single best/most-canonical story unchanged, and propose a REWRITE for the OTHER story(ies) so each becomes genuinely distinct.

RULES:
- Only propose rewrites for stories with number >= ${d.minRewritable}. Never rewrite a lower-numbered (canonical/published) story.
- Be SELECTIVE: only rewrite where premise AND lesson are near-identical. If stories merely share a character or broad setting but have different plots/lessons, do NOT rewrite them.
- For each rewrite: give a genuinely DIFFERENT activity/plot AND a DIFFERENT emotional lesson (theme) from every other story in the collection (and from the canonical list). To break "same character, same arc" repetition, you SHOULD often switch the main character to a DIFFERENT or NEW food character of this culture (avoid the over-used ones), and change the setting and title accordingly.
- Keep it cozy, funny, bedtime-safe, on-culture. Keep the local-language spotlight in the right language (${COLL_LANG(key)}).
- A story may appear in multiple clusters — only revise it once.
- Output ONLY the stories you are actually rewriting (the ones to change), not the ones you keep.

CLUSTERS FOUND:
${clusterList}
${existingList}

FULL ${key} ROADMAP (number, title, character, theme, premise):
${roadmapList}

Return the list of revisions.`
  return agent(prompt, {label:`diff:${key}`, phase:'Plan revisions', schema:SCHEMA})
    .then(r=>({collection:key, revisions:r.revisions||[]})).catch(()=>({collection:key, revisions:[]}))
}))

function COLL_LANG(k){return ({taiwan:'Mandarin',hawaii:'Hawaiian',['costa-rica']:'Spanish',japan:'Japanese'})[k]}

const summary = results.map(r=>({collection:r.collection, rewrites:r.revisions.length}))
log('Revisions planned: '+JSON.stringify(summary))
return { results }
